let mensaje;
try {
  const d = $input.first().json || {};
  const ex = d.execution || {};
  const wf = d.workflow || {};
  const err = ex.error || d.error || {};
  const ctx = ex.executionContext || {};
  const trigger = (ctx.triggerNode && ctx.triggerNode.name) || ctx.source || 'desconocido';
  let msg = err.message || err.description || 'sin detalle';
  msg = String(msg).replace(/\s*\[line \d+\]\s*$/, '');
  const nodo = ex.lastNodeExecuted
    || (typeof err.node === 'object' && err.node ? (err.node.name || err.node.type) : err.node)
    || 'desconocido';
  const partes = [
    'FALLO UN WORKFLOW',
    'Workflow: ' + (wf.name || 'desconocido') + (wf.id ? ' (' + wf.id + ')' : ''),
    'Error: ' + msg,
    'Nodo: ' + nodo,
    'Trigger: ' + trigger,
    'Execution: ' + (ex.id || 'n/d')
  ];
  if (ex.url) partes.push('Ver: ' + ex.url);
  mensaje = partes.join('\n');
} catch (e) {
  mensaje = 'FALLO UN WORKFLOW (no pude leer el detalle): ' + (e && e.message);
}
return [{ json: { mensaje } }];
